<?php
declare(strict_types=1);
$attentionQuery = $query;
unset($attentionQuery['status'], $attentionQuery['attention']);
$attentionUrl = '/csi/requests?' . http_build_query([...$attentionQuery, 'attention' => 'needed']);
$sortQuery = $query;
unset($sortQuery['sort']);
$requestDate = static function (string $value): array {
    $date = (new DateTimeImmutable($value))->setTimezone(new DateTimeZone('America/Lima'));
    $today = new DateTimeImmutable('today', new DateTimeZone('America/Lima'));
    $day = $date->format('Y-m-d');
    $label = $day === $today->format('Y-m-d') ? 'Hoy, ' . $date->format('H:i') : ($day === $today->modify('-1 day')->format('Y-m-d') ? 'Ayer, ' . $date->format('H:i') : $date->format('d/m/Y, H:i'));
    return [$date->format(DATE_ATOM), $label, $date->format('d/m/Y')];
};
?>
<section class="csi-list-card" aria-label="Listado de solicitudes">
  <div class="csi-list-card__toolbar"><nav class="csi-list-tabs" aria-label="Filtrar por estado de atención"><?php foreach ($tabs as [$label, $count, $statusId]): $active = $statusId === null ? $selectedStatus === '' : $selectedStatus === (string) $statusId; ?><a href="<?= $e($tabUrl($statusId)) ?>" <?= $active ? 'aria-current="page"' : '' ?>><?= $e($label) ?> <span>(<?= (int) $count ?>)</span></a><?php endforeach; ?></nav><a class="csi-list-attention" href="<?= $e($attentionUrl) ?>" <?= ($_GET['attention'] ?? '') === 'needed' ? 'aria-current="page"' : '' ?>><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" aria-hidden="true"><path d="m12 3 10 18H2L12 3Z"/><path d="M12 9v5m0 3h.01"/></svg>Requiere intervención (<?= (int) $listAttentionCount ?>)<span aria-hidden="true">→</span></a></div>
  <form class="csi-list-sort" method="get" action="/csi/requests"><label for="sort">Ordenar por:</label><?php foreach ($sortQuery as $key => $value): if (!is_string($value)) { continue; } ?><input type="hidden" name="<?= $e($key) ?>" value="<?= $e($value) ?>"><?php endforeach; ?><select id="sort" name="sort" onchange="this.form.requestSubmit()"><option value="recent" <?= ($_GET['sort'] ?? 'recent') === 'recent' ? 'selected' : '' ?>>Más recientes</option><option value="oldest" <?= ($_GET['sort'] ?? '') === 'oldest' ? 'selected' : '' ?>>Más antiguos</option></select><button class="sr-only focus:not-sr-only" type="submit">Aplicar orden</button></form>
  <?php if ($listing['items'] === []): ?><div class="csi-list-empty"><h2>No hay solicitudes para mostrar</h2><p>Prueba con otros filtros o espera nuevas solicitudes.</p></div><?php else: ?>
  <div class="csi-list-table-wrap"><table class="csi-list-table"><caption class="sr-only">Solicitudes filtradas</caption><thead><tr><th scope="col">Código / asunto</th><th scope="col">Oficina / área</th><th scope="col">Registro <span aria-hidden="true"><?= ($_GET['sort'] ?? 'recent') === 'oldest' ? '↑' : '↓' ?></span></th><th scope="col">Prioridad</th><th scope="col">Estado</th><th scope="col">Asignado</th><th scope="col">Acciones</th></tr></thead><tbody>
  <?php foreach ($listing['items'] as $item):
    $code = $item['status_code'] ?? '';
    $priority = mb_strtolower((string) ($item['priority_name'] ?? ''));
    $priorityClass = str_contains($priority, 'urgent') || str_contains($priority, 'crític') ? 'urgent' : (str_contains($priority, 'alta') ? 'high' : (str_contains($priority, 'baja') ? 'low' : 'normal'));
    $detailUrl = '/csi/requests/' . rawurlencode($item['public_code']);
    [$dateTime, $dateLabel, $dateShort] = $requestDate($item['created_at']);
  ?>
    <tr><td data-label="Código / asunto"><div class="csi-list-request"><span class="csi-list-request__icon" aria-hidden="true"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><path d="M5 3h10l4 4v14H5zM14 3v5h5M8 12h8M8 16h8"/></svg></span><span><a class="csi-list-code" href="<?= $e($detailUrl) ?>"><?= $e($item['public_code']) ?></a><strong class="csi-list-subject"><?= $e($item['title']) ?></strong></span></div></td><td data-label="Oficina / área"><?= $e($item['area_name']) ?></td><td data-label="Registro"><time class="csi-list-date" datetime="<?= $e($dateTime) ?>"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" aria-hidden="true"><rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 3v4M17 3v4M3 10h18"/></svg><span><?= $e($dateLabel) ?><small><?= $e($dateShort) ?></small></span></time></td><td data-label="Prioridad"><span class="csi-list-badge csi-list-badge--<?= $priorityClass ?>"><?= $e($item['priority_name'] ?? 'Sin prioridad') ?></span></td><td data-label="Estado"><span class="csi-list-badge csi-list-badge--<?= $e($code) ?>"><?= $e($item['status_name']) ?></span></td><td data-label="Asignado"><span class="csi-list-assignee"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" aria-hidden="true"><circle cx="12" cy="8" r="3"/><path d="M5 20c0-4 3-6 7-6s7 2 7 6"/></svg><?= $item['technician_name'] === null ? '<em>Sin asignar</em>' : $e(\App\Presentation\DisplayName::withoutDemoMarker($item['technician_name'])) ?></span></td><td data-label="Acciones"><div class="csi-list-actions"><a href="<?= $e($detailUrl) ?>" class="csi-list-view" aria-label="Ver detalle de <?= $e($item['public_code']) ?>"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" aria-hidden="true"><path d="M2 12s3.5-6 10-6 10 6 10 6-3.5 6-10 6-10-6-10-6Z"/><circle cx="12" cy="12" r="3"/></svg>Ver detalle</a><details class="csi-list-more"><summary aria-label="Más acciones para <?= $e($item['public_code']) ?>" title="Más acciones">···</summary><div><a href="<?= $e($detailUrl) ?>">Ver detalle</a><?php if (!in_array($code, ['resolved', 'closed', 'cancelled'], true)): ?><?php if ($user->can('request.assign')): ?><a href="<?= $e($detailUrl) ?>#asignar-responsable">Asignar o reasignar</a><?php endif; ?><?php if ($user->can('request.classify')): ?><a href="<?= $e($detailUrl) ?>">Clasificar y priorizar</a><?php endif; ?><?php endif; ?></div></details></div></td></tr>
  <?php endforeach; ?></tbody></table></div>
  <nav class="csi-list-pagination" aria-label="Páginas de solicitudes"><span>Mostrando <?= (($listing['page'] - 1) * 5) + 1 ?>–<?= min($listing['page'] * 5, $listing['total']) ?> de <?= (int) $listing['total'] ?> registros</span><div><?php if ($listing['page'] > 1): ?><a href="<?= $e($pageUrl($listing['page'] - 1)) ?>" aria-label="Página anterior">‹</a><?php endif; ?><strong aria-current="page"><?= (int) $listing['page'] ?></strong><span>de <?= (int) $listing['pages'] ?></span><?php if ($listing['page'] < $listing['pages']): ?><a href="<?= $e($pageUrl($listing['page'] + 1)) ?>" aria-label="Página siguiente">›</a><?php endif; ?></div></nav>
  <?php endif; ?>
</section>
